    AppLocale.zu => const AppLocalizationsZu(),
  };

  /// Parses a locale tag such as `en` or `pt-BR`.
  ///
  /// Returns `null` when no supported locale matches exactly.
  static AppLocale? tryParse(String tag) {
    final locale = L10nLocale.tryParse(tag);
    if (locale == null) return null;
    for (final value in values) {
      if (value.l10nLocale == locale) return value;
    }
    return null;
  }
}

/// Locale independent translation API.
///
/// Obtain an instance with [AppLocalizations.of], [AppLocalizations.forLocale] or
/// [AppLocale.translations].
abstract interface class AppLocalizations implements BaseTranslations {
  /// Every supported locale.
  static const List<AppLocale> supportedLocales = AppLocale.values;

  /// The locale used when no supported locale matches.
  static const AppLocale fallbackLocale = AppLocale.en;

  /// Translations of [locale], without any `BuildContext`.
  static AppLocalizations forLocale(AppLocale locale) => locale.translations;

  /// Best translations for [locale], applying the fallback
  /// chain `locale -> language -> fallbackLocale`.
  static AppLocalizations of(L10nLocale? locale) =>
      resolve(locale).translations;

  /// The supported locale that best matches [locale].
  static AppLocale resolve(L10nLocale? locale) => L10nLocaleResolver.resolve(
    requested: locale,
    supported: supportedLocales,
    fallback: fallbackLocale,
  );

  /// The locale these translations belong to.
  AppLocale get appLocale;

  /// `en`: {count, plural, ...}
  String cat({required num count});
}

