  @override
  L10nLocale get l10nLocale => const L10nLocale('be');

  @override
  String cat({required num count}) {
    final $operands = PluralOperands(count);
    if ($operands.n % 10 == 1 && $operands.n % 100 != 11) {
      return 'one';
