    if ($operands.n == $operands.i &&
        $operands.n % 10 >= 2 &&
        $operands.n % 10 <= 4 &&
        !($operands.n == $operands.i &&
            $operands.n % 100 >= 12 &&
            $operands.n % 100 <= 14)) {
      return 'few';
    }
    if ($operands.n % 10 == 0 ||
        $operands.n == $operands.i &&
            $operands.n % 10 >= 5 &&
            $operands.n % 10 <= 9 ||
        $operands.n == $operands.i &&
            $operands.n % 100 >= 11 &&
            $operands.n % 100 <= 14) {
      return 'many';
    }
    return 'other';
  }
}

