/// `br` translations.
class AppLocalizationsBr implements AppLocalizations {
  /// Creates the br translations.
  const AppLocalizationsBr();

  @override
  AppLocale get appLocale => AppLocale.br;

  @override
  L10nLocale get l10nLocale => const L10nLocale('br');

  @override
  String cat({required num count}) {
    final $operands = PluralOperands(count);
    if ($operands.n % 10 == 1 &&
        $operands.n % 100 != 11 &&
        $operands.n % 100 != 71 &&
        $operands.n % 100 != 91) {
      return 'one';
    }
    if ($operands.n % 10 == 2 &&
        $operands.n % 100 != 12 &&
        $operands.n % 100 != 72 &&
        $operands.n % 100 != 92) {
      return 'two';
    }
    if (($operands.n == $operands.i &&
                $operands.n % 10 >= 3 &&
                $operands.n % 10 <= 4 ||
            $operands.n % 10 == 9) &&
        !($operands.n == $operands.i &&
                $operands.n % 100 >= 10 &&
                $operands.n % 100 <= 19 ||
            $operands.n == $operands.i &&
                $operands.n % 100 >= 70 &&
                $operands.n % 100 <= 79 ||
            $operands.n == $operands.i &&
                $operands.n % 100 >= 90 &&
                $operands.n % 100 <= 99)) {
      return 'few';
    }
    if ($operands.n != 0 && $operands.n % 1000000 == 0) {
      return 'many';
    }
    return 'other';
  }
}

