/// `sr` translations.
class AppLocalizationsSr implements AppLocalizations {
  /// Creates the sr translations.
  const AppLocalizationsSr();

  @override
  AppLocale get appLocale => AppLocale.sr;

  @override
  L10nLocale get l10nLocale => const L10nLocale('sr');

  @override
  String cat({required num count}) {
    final $operands = PluralOperands(count);
    if ($operands.v == 0 && $operands.i % 10 == 1 && $operands.i % 100 != 11 ||
        $operands.f % 10 == 1 && $operands.f % 100 != 11) {
      return 'one';
    }
    if ($operands.v == 0 &&
            $operands.i % 10 >= 2 &&
            $operands.i % 10 <= 4 &&
            !($operands.i % 100 >= 12 && $operands.i % 100 <= 14) ||
        $operands.f % 10 >= 2 &&
            $operands.f % 10 <= 4 &&
            !($operands.f % 100 >= 12 && $operands.f % 100 <= 14)) {
      return 'few';
    }
    return 'other';
  }
}

