/// `uk` translations.
class AppLocalizationsUk implements AppLocalizations {
  /// Creates the uk translations.
  const AppLocalizationsUk();

  @override
  AppLocale get appLocale => AppLocale.uk;

  @override
  L10nLocale get l10nLocale => const L10nLocale('uk');

  @override
  String cat({required num count}) {
    final $operands = PluralOperands(count);
    if ($operands.v == 0 && $operands.i % 10 == 1 && $operands.i % 100 != 11) {
      return 'one';
    }
    if ($operands.v == 0 &&
        $operands.i % 10 >= 2 &&
        $operands.i % 10 <= 4 &&
        !($operands.i % 100 >= 12 && $operands.i % 100 <= 14)) {
      return 'few';
    }
    if ($operands.v == 0 && $operands.i % 10 == 0 ||
        $operands.v == 0 && $operands.i % 10 >= 5 && $operands.i % 10 <= 9 ||
        $operands.v == 0 &&
            $operands.i % 100 >= 11 &&
            $operands.i % 100 <= 14) {
      return 'many';
    }
    return 'other';
  }
}

